-- Import the 328-entry NUC university roster (77 Federal, 69 State, 182 Private).
-- Name/category rows are from the NUC-sourced category reference snapshot fetched 2026-09-05;
-- the official NUC eNUC page currently reports the same totals: https://enuc.nuc.edu.ng/nus
-- States and available official websites were reconciled from the institution location list.
-- Preserve IDs and slugs for the starter records so any existing membership foreign keys remain valid.
begin;

update public.campus_universities as u
set name = v.name,
    ownership = v.ownership,
    state = v.state,
    source_url = 'https://enuc.nuc.edu.ng/nus',
    official_website = coalesce(nullif(v.official_website,''),u.official_website),
    is_active = true,
    updated_at = now()
from (values
('abia-state-university','Abia State University, Uturu','State','Abia','https://abiastateuniversity.edu.ng'),
('abubakar-tafawa-balewa-university','Abubakar Tafawa Balewa University, Bauchi','Federal','Bauchi','https://atbu.edu.ng'),
('ahmadu-bello-university','Ahmadu Bello University, Zaria','Federal','Kaduna','https://abu.edu.ng'),
('american-university-of-nigeria','American University of Nigeria, Yola','Private','Adamawa','https://aun.edu.ng'),
('babcock-university','Babcock University, Ilishan-Remo','Private','Ogun','https://babcock.edu.ng'),
('bayero-university-kano','Bayero University, Kano','Federal','Kano','https://buk.edu.ng'),
('bowen-university','Bowen University, Iwo','Private','Osun','https://bowen.edu.ng'),
('covenant-university','Covenant University Ota','Private','Ogun','https://covenantuniversity.edu.ng'),
('delta-state-university','Delta State University Abraka','State','Delta','https://delsu.edu.ng'),
('ekiti-state-university','Ekiti State University','State','Ekiti','https://eksu.edu.ng'),
('federal-university-dutse','Federal University, Dutse, Jigawa State','Federal','Jigawa','https://fud.edu.ng'),
('federal-university-oye-ekiti','Federal University, Oye-Ekiti, Ekiti State','Federal','Ekiti','https://fuoye.edu.ng'),
('federal-university-of-technology-akure','Federal University of Technology, Akure','Federal','Ondo','https://futa.edu.ng'),
('federal-university-of-technology-minna','Federal University of Technology, Minna','Federal','Niger','https://futminna.edu.ng'),
('federal-university-of-technology-owerri','Federal University of Technology, Owerri','Federal','Imo','https://futo.edu.ng'),
('lagos-state-university','Lagos State University, Ojo','State','Lagos','https://lasu.edu.ng'),
('nnamdi-azikiwe-university','Nnamdi Azikiwe University, Awka','Federal','Anambra','https://unizik.edu.ng'),
('obafemi-awolowo-university','Obafemi Awolowo University, Ile-Ife','Federal','Osun','https://oauife.edu.ng'),
('pan-atlantic-university','Pan-Atlantic University, Lagos','Private','Lagos','https://pau.edu.ng'),
('redeemers-university','Redeemer''s University, Ede','Private','Osun','https://run.edu.ng'),
('rivers-state-university','Rivers State University','State','Rivers','https://rsu.edu.ng'),
('university-of-abuja','University of Abuja, Gwagwalada','Federal','FCT Abuja','https://uniabuja.edu.ng'),
('university-of-benin','University of Benin','Federal','Edo','https://uniben.edu.ng'),
('university-of-calabar','University of Calabar','Federal','Cross River','https://unical.edu.ng'),
('university-of-ibadan','University of Ibadan','Federal','Oyo','https://ui.edu.ng'),
('university-of-ilorin','University of Ilorin','Federal','Kwara','https://unilorin.edu.ng'),
('university-of-jos','University of Jos','Federal','Plateau','https://unijos.edu.ng'),
('university-of-lagos','University of Lagos','Federal','Lagos','https://unilag.edu.ng'),
('university-of-maiduguri','University of Maiduguri','Federal','Borno','https://unimaid.edu.ng'),
('university-of-nigeria-nsukka','University of Nigeria, Nsukka','Federal','Enugu','https://unn.edu.ng'),
('university-of-port-harcourt','University of Port-Harcourt','Federal','Rivers','https://uniport.edu.ng'),
('university-of-uyo','University of Uyo','Federal','Akwa Ibom','https://uniuyo.edu.ng'),
('osun-state-university','Osun State University Osogbo','State','Osun','https://uniosun.edu.ng'),
('kwara-state-university','Kwara State University, Ilorin','State','Kwara','https://kwasu.edu.ng'),
('nasarawa-state-university','Nasarawa State University Keffi','State','Nasarawa','https://nsuk.edu.ng'),
('kano-university-science-technology','Aliko Dangote University of Science & Technology, Wudil','State','Kano','https://kust.edu.ng'),
('modibbo-adama-university','Modibbo Adama University of Technology, Yola','Federal','Adamawa','https://mautech.edu.ng'),
('michael-okpara-university','Michael Okpara University of Agricultural Umudike','Federal','Abia','https://mouau.edu.ng'),
('federal-university-agriculture-abeokuta','Federal University of Agriculture, Abeokuta','Federal','Ogun','https://unaab.edu.ng'),
('federal-university-technology-babura','Federal University of Technology, Babura, Jigawa State','Federal','Jigawa',null)
) as v(slug,name,ownership,state,official_website)
where u.slug = v.slug;

on conflict (slug) do update
set name=excluded.name,
    ownership=excluded.ownership,
    state=excluded.state,
    source_url=excluded.source_url,
    official_website=coalesce(excluded.official_website,public.campus_universities.official_website),
    is_active=true,
    updated_at=now();

commit;
